// Runs before any HTTP request. Both HTTP nodes may only call the local sanitizing
// relay (backend/app/demo_relay.py): the API's own 201 response carries a client
// bearer-token link, and n8n shows every node's output in the editor. This reads
// the HTTP nodes' own settings and stops the run, before anything is sent, if
// either one was changed to point anywhere else.
const RELAY_ENDPOINT = 'http://127.0.0.1:8011/api/webhooks/crm/deal-won';
const problems = [];
for (const name of ['Send Deal-Won Event', 'Replay Deal-Won Event']) {
  let p;
  try { p = $(name).params; } catch (e) { p = undefined; }
  if (!p || typeof p !== 'object') { problems.push(`${name}: node not found`); continue; }
  if (p.url !== RELAY_ENDPOINT) problems.push(`${name}: URL must be exactly ${RELAY_ENDPOINT}`);
  if (String(p.method) !== 'POST') problems.push(`${name}: method must be POST`);
  if (p.sendQuery) problems.push(`${name}: query parameters are not allowed`);
  const o = p.options && typeof p.options === 'object' ? p.options : {};
  if (o.proxy) problems.push(`${name}: a proxy is not allowed`);
  if (o.redirect?.redirect?.followRedirects !== false) problems.push(`${name}: redirects must not be followed`);
}
if (problems.length) {
  throw new Error(`Relay endpoint check failed: ${problems.join('; ')}. No request was sent.`);
}
return $input.all();

// Normalization boundary: a CRM-style example -> the backend's generic deal.won contract
// (backend/app/schemas/crm.py). The examples are copied verbatim from
// docs/examples/crm/*.json and contain synthetic data only. GoHighLevel and HubSpot
// here are payload STYLES, not live integrations.
const EXAMPLES = {
  "generic": {
    "event_id": "evt_2026_0001",
    "event_type": "deal.won",
    "occurred_at": "2026-11-07T18:00:00Z",
    "source": "generic",
    "deal": {
      "external_id": "deal_123",
      "name": "Website Development Project",
      "value": 2500,
      "currency": "USD",
      "service_type": "website_build"
    },
    "contact": {
      "external_id": "contact_456",
      "name": "Demo Client",
      "email": "client@example.com",
      "company": "Example Company",
      "phone": "+10000000000"
    }
  },
  "gohighlevel": {
    "event_id": "ghl_opp_status_8f2c1e4a-won",
    "event_type": "deal.won",
    "occurred_at": "2026-11-07T15:42:10+00:00",
    "source": "gohighlevel",
    "deal": {
      "external_id": "opp_7Hk2Lq9Zt4",
      "name": "Local SEO - Monthly Retainer",
      "value": 1200,
      "currency": "USD",
      "service_type": "seo_retainer"
    },
    "contact": {
      "external_id": "cnt_Xa81PqR2mN",
      "name": "Jordan Rivera",
      "email": "jordan@riverabakery.example",
      "company": "Rivera Bakery",
      "phone": "+15555550123"
    }
  },
  "hubspot": {
    "event_id": "hs-deal-18842211907-closedwon-1730994000",
    "event_type": "deal.won",
    "occurred_at": "2026-11-07T16:20:00Z",
    "source": "hubspot",
    "deal": {
      "external_id": "18842211907",
      "name": "Marketing Automation Rollout",
      "value": 4800.0,
      "currency": "EUR",
      "service_type": "marketing_automation_setup"
    },
    "contact": {
      "external_id": "95510231",
      "name": "Sam Okafor",
      "email": "sam.okafor@northwind.example",
      "company": "Northwind Analytics",
      "phone": null
    }
  }
};

// One explicit mapping per format: which source label it must carry and the prefix
// used for the per-execution demo IDs.
const FORMATS = {
  generic:     { source: 'generic',     prefix: 'gen' },
  gohighlevel: { source: 'gohighlevel', prefix: 'ghl' },
  hubspot:     { source: 'hubspot',     prefix: 'hs'  },
};
const SERVICE_TYPES = ['website_build', 'seo_retainer', 'marketing_automation_setup'];

const settings = $('Select CRM Example').first().json;
const demoId = $('Generate Demo ID').first().json.demo_id;
const format = String(settings.crm_format ?? '').trim().toLowerCase();
if (!FORMATS[format]) {
  throw new Error(`Normalization failed: crm_format must be generic, gohighlevel or hubspot (got "${format}")`);
}
if (typeof demoId !== 'string' || !/^[0-9a-f-]{36}$/.test(demoId)) {
  throw new Error('Normalization failed: no demo ID was generated');
}

const src = EXAMPLES[format];
const { source, prefix } = FORMATS[format];
const fail = (field, why) => { throw new Error(`Normalization failed: ${field} ${why}`); };
const text = (value, field, { required = true, max = 300 } = {}) => {
  if (value === undefined || value === null || (typeof value === 'string' && value.trim() === '')) {
    if (required) fail(field, 'is required');
    return null;
  }
  if (typeof value !== 'string') fail(field, 'must be text');
  const v = value.trim();
  if (v.length > max) fail(field, `must be at most ${max} characters`);
  return v;
};

if (src.source !== source) fail('source', `must be "${source}" for the ${format} example`);
if (src.event_type !== 'deal.won') fail('event_type', 'must be deal.won');

const value = src.deal.value;
if (value !== null && value !== undefined) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) fail('deal.value', 'must be a non-negative number');
  if (Math.round(value * 100) !== value * 100) fail('deal.value', 'must have at most 2 decimals');
}
const currency = value === null || value === undefined ? null : text(src.deal.currency, 'deal.currency', { max: 3 }).toUpperCase();
if (currency !== null && !/^[A-Z]{3}$/.test(currency)) fail('deal.currency', 'must be a 3-letter code');
const serviceType = text(src.deal.service_type, 'deal.service_type', { max: 64 });
if (!SERVICE_TYPES.includes(serviceType)) fail('deal.service_type', `must be one of ${SERVICE_TYPES.join(', ')}`);

const email = text(src.contact.email, 'contact.email', { required: false, max: 254 });
const contactId = text(src.contact.external_id, 'contact.external_id', { required: false, max: 200 });
if (email !== null && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) fail('contact.email', 'is not an email address');
if (email === null && contactId === null) fail('contact', 'needs external_id or email');
const phone = text(src.contact.phone, 'contact.phone', { required: false, max: 40 });
if (phone !== null && !/^[0-9+()\-. ]{3,40}$/.test(phone)) fail('contact.phone', 'has unsupported characters');

// Field-by-field construction: nothing from the example is passed through unchecked.
// Event and deal IDs are unique per execution, so a run never replays an old event.
const normalized = {
  event_id: `n8n-demo-${prefix}-${demoId}`,
  event_type: 'deal.won',
  occurred_at: new Date().toISOString(),
  source,
  deal: {
    external_id: `${text(src.deal.external_id, 'deal.external_id', { max: 120 })}-${demoId}`,
    name: text(src.deal.name, 'deal.name', { required: false }),
    value: value ?? null,
    currency,
    service_type: serviceType,
  },
  contact: {
    external_id: contactId,
    name: text(src.contact.name, 'contact.name', { max: 200 }),
    email: email === null ? null : email.toLowerCase(),
    company: text(src.contact.company, 'contact.company', { required: false }),
    phone,
  },
};
return [{ json: { crm_format: format, normalized } }];

// Serialize ONCE. This exact string is what gets signed and what gets sent, for both
// the first request and the replay. Nothing downstream parses or re-serializes it.
const { normalized, crm_format } = $input.first().json;
const body = JSON.stringify(normalized);
return [{ json: {
  body,
  event_id: normalized.event_id,
  deal_id: normalized.deal.external_id,
  crm_format,
} }];

// The relay already removed the onboarding link (it carries a client bearer token).
// Keep only the IDs and the outcome.
// The relay returns only these fields; anything else means the request did not go
// through the sanitizing relay, so stop immediately and pass nothing on.
const RELAY_FIELDS = ['status', 'client_id', 'invitation_id', 'event_id', 'code', 'field', 'relay'];
const res = $input.first().json;
const status = res.statusCode;
const body = res.body && typeof res.body === 'object' && !Array.isArray(res.body) ? res.body : {};
const unexpected = Object.keys(body).filter((k) => !RELAY_FIELDS.includes(k));
if (unexpected.length) {
  throw new Error(`Unsafe response: ${unexpected.length} field(s) outside the relay allowlist. Did the request bypass the relay?`);
}

const eventId = $('Build Exact Raw Body').first().json.event_id;
if (status === 201 && body.status === 'created' && typeof body.client_id === 'string') {
  return [{ json: {
    event_id: eventId,
    first_status: 201,
    first_result: 'created',
    client_id: body.client_id,
    invitation_id: typeof body.invitation_id === 'string' ? body.invitation_id : null,
  } }];
}
const code = typeof body.code === 'string' ? body.code : null;
const field = typeof body.field === 'string' ? body.field : null;
const meaning = {
  200: 'the event was already processed earlier (not a new event)',
  401: 'signature rejected: the Crypto credential must equal the backend CRM_WEBHOOK_SECRET',
  409: 'conflict (event ID reused with different data, or client identity conflict)',
  413: 'payload too large',
  415: 'wrong content type',
  422: 'payload rejected by validation',
  502: code === 'upstream_unreachable' ? 'the relay could not reach the API (is it running on its port?)'
     : 'the relay received an unexpected response from the API',
  503: 'backend not ready (is CRM_WEBHOOK_SECRET set?)',
}[status] || 'unexpected response';
throw new Error(`First request failed: HTTP ${status}${code ? ` (${code})` : ''}${field ? ` at ${field}` : ''}: ${meaning}. Replay was not sent.`);

// HTTP Request error output: the relay could not be reached (no HTTP response).
const url = 'http://127.0.0.1:8011';
const err = $input.first().json.error || {};
const reason = String(err.code || err.description || err.message || 'connection error').slice(0, 120);
throw new Error(`Relay not reachable at ${url}: ${reason}. Start the relay and the API (see docs/n8n-demo.md).`);

// Fresh timestamp for the replay, strictly later than the first one, so the replay
// carries a new signature over the SAME body.
const first = Number($('Create Webhook Timestamp').first().json.timestamp);
let now = Math.floor(Date.now() / 1000);
if (now <= first) {
  const until = (first + 1) * 1000 + 20;
  if (typeof setTimeout === 'function') {
    await new Promise((resolve) => setTimeout(resolve, until - Date.now()));
  }
  while (Date.now() < until) { /* at most ~1 s */ }
  now = Math.floor(Date.now() / 1000);
}
const built = $('Build Exact Raw Body').first().json;
return [{ json: {
  body: built.body,
  event_id: built.event_id,
  timestamp: String(now),
} }];

// The identical event must be recognised as a duplicate (HTTP 200).
// The relay returns only these fields; anything else means the request did not go
// through the sanitizing relay, so stop immediately and pass nothing on.
const RELAY_FIELDS = ['status', 'client_id', 'invitation_id', 'event_id', 'code', 'field', 'relay'];
const res = $input.first().json;
const status = res.statusCode;
const body = res.body && typeof res.body === 'object' && !Array.isArray(res.body) ? res.body : {};
const unexpected = Object.keys(body).filter((k) => !RELAY_FIELDS.includes(k));
if (unexpected.length) {
  throw new Error(`Unsafe response: ${unexpected.length} field(s) outside the relay allowlist. Did the request bypass the relay?`);
}

const eventId = $('Build Exact Raw Body').first().json.event_id;
if (status === 200 && body.status === 'duplicate' && body.event_id === eventId) {
  return [{ json: { replay_status: 200, replay_result: 'duplicate' } }];
}
if (status === 201) {
  throw new Error('Replay failed: the backend accepted the replay as a NEW event (idempotency failure).');
}
const code = typeof body.code === 'string' ? body.code : (typeof body.status === 'string' ? body.status : null);
throw new Error(`Replay failed: expected HTTP 200 duplicate, got HTTP ${status}${code ? ` (${code})` : ''}.`);

// Replay error output: the relay could not be reached (no HTTP response).
const url = 'http://127.0.0.1:8011';
const err = $input.first().json.error || {};
const reason = String(err.code || err.description || err.message || 'connection error').slice(0, 120);
throw new Error(`Relay not reachable at ${url}: ${reason}. Start the relay and the API (see docs/n8n-demo.md).`);

// The only output of the demo: safe identifiers and outcomes. No request body,
// signature, credential, onboarding URL or token.
const built = $('Build Exact Raw Body').first().json;
const first = $('Validate First Response').first().json;
const replay = $('Validate Replay').first().json;
return [{ json: {
  result: 'success',
  crm_format: built.crm_format,
  event_id: built.event_id,
  deal_id: built.deal_id,
  first_request: { status: first.first_status, result: first.first_result,
                   client_id: first.client_id, invitation_id: first.invitation_id },
  replay: { status: replay.replay_status, result: replay.replay_result },
  message: 'The deal-won event was accepted once and the identical replay was recognised as a duplicate. The client invitation link was not exposed.',
} }];
